#include <vector>
#include <omp.h>

void reversePrefixSum(std::vector<int> const& x, std::vector<int> &output) {
    const int n = static_cast<int>(x.size());
    output.resize(n);
    if (n == 0) return;

    int max_threads = 1;
    #pragma omp parallel
    {
        #pragma omp single
        {
            max_threads = omp_get_num_threads();
        }
    }

    std::vector<long long> blockSums(max_threads + 1, 0LL);

    #pragma omp parallel
    {
        const int tid = omp_get_thread_num();
        const int T   = omp_get_num_threads();

        const int chunk = (n + T - 1) / T;
        const int start = tid * chunk;
        int end = start + chunk;
        if (end > n) end = n;

        long long localSum = 0;

        // Local reverse prefix within each block:
        // output[i] = sum_{k=start..i} x[k]
        if (start < end) {
            localSum = x[start];
            output[start] = static_cast<int>(localSum);
            for (int i = start + 1; i < end; ++i) {
                localSum += x[i];
                output[i] = static_cast<int>(localSum);
            }
        }

        blockSums[tid + 1] = localSum;

        #pragma omp barrier

        // One thread computes prefix of block sums (offset for each block)
        #pragma omp single
        {
            for (int t = 1; t <= T; ++t) {
                blockSums[t] += blockSums[t - 1];
            }
        }

        #pragma omp barrier

        // Add offset from previous blocks
        const long long offset = blockSums[tid];
        for (int i = start; i < end; ++i) {
            output[i] = static_cast<int>(static_cast<long long>(output[i]) + offset);
        }
    }
}
